-- CWCT website and management schema. Review policies before production use.
create table if not exists public.user_roles(id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin');
create or replace function public.is_cwct_admin() returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.user_roles where id=auth.uid() and role in ('admin','super_admin','management')); $$;
create table if not exists public.projects(id bigint generated by default as identity primary key,title text not null,category text,description text,image text,published boolean default false,created_at timestamptz default now());
create table if not exists public.activities(id bigint generated by default as identity primary key,title text not null,date text,description text,image text,published boolean default false,created_at timestamptz default now());
create table if not exists public.gallery(id bigint generated by default as identity primary key,title text,image text,published boolean default false,created_at timestamptz default now());
create table if not exists public.contact_messages(id bigint generated by default as identity primary key,name text not null,email text not null,phone text,subject text,message text not null,created_at timestamptz default now());
create table if not exists public.volunteer_submissions(id bigint generated by default as identity primary key,name text not null,email text not null,phone text,interest text,message text,created_at timestamptz default now());
create table if not exists public.members(id bigint generated by default as identity primary key,full_name text not null,email text,phone text,membership_type text,joined_on date,notes text,created_at timestamptz default now());
create table if not exists public.wildlife_reports(id bigint generated by default as identity primary key,report_title text not null,incident_type text,location text,report_date date,details text,status text default 'Open',created_at timestamptz default now());
create table if not exists public.donations(id bigint generated by default as identity primary key,donor_name text not null,amount numeric(12,2) not null default 0,donation_date date,receipt_reference text,purpose text,created_at timestamptz default now());
create table if not exists public.documents(id bigint generated by default as identity primary key,title text not null,category text,url text,notes text,created_at timestamptz default now());
-- Public can read published site content. Only authenticated admins can write.
do $$ declare t text; begin foreach t in array array['projects','activities','gallery','contact_messages','volunteer_submissions','members','wildlife_reports','donations','documents','user_roles'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['projects','activities','gallery'] loop execute format('drop policy if exists public_read_published on public.%I',t); execute format('create policy public_read_published on public.%I for select using (published = true or public.is_cwct_admin())',t); execute format('drop policy if exists admin_manage on public.%I',t); execute format('create policy admin_manage on public.%I for all to authenticated using (public.is_cwct_admin()) with check (public.is_cwct_admin())',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['members','wildlife_reports','donations','documents','contact_messages','volunteer_submissions'] loop execute format('drop policy if exists admin_manage on public.%I',t); execute format('create policy admin_manage on public.%I for all to authenticated using (public.is_cwct_admin()) with check (public.is_cwct_admin())',t); end loop; end $$;
-- Public form submissions; use CAPTCHA/edge function and rate limits for production.
drop policy if exists public_submit_contact on public.contact_messages; create policy public_submit_contact on public.contact_messages for insert to anon,authenticated with check (true);
drop policy if exists public_submit_volunteer on public.volunteer_submissions; create policy public_submit_volunteer on public.volunteer_submissions for insert to anon,authenticated with check (true);


-- Website CMS: stores individually editable page content and design settings as JSON.
create table if not exists public.site_settings (id text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz default now(), updated_by uuid references auth.users(id) on delete set null);
alter table public.site_settings enable row level security;
drop policy if exists public_read_site_settings on public.site_settings;
create policy public_read_site_settings on public.site_settings for select to anon, authenticated using (id = 'site_content' or public.is_cwct_admin());
drop policy if exists admin_manage_site_settings on public.site_settings;
create policy admin_manage_site_settings on public.site_settings for all to authenticated using (public.is_cwct_admin()) with check (public.is_cwct_admin());
